with q as (select * from (values
('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-constitution-sixthpart-10','Constituição do Acre — sexta-parte','Conforme o art. 36, § 4º, da Constituição do Estado do Acre, a gratificação de sexta-parte é concedida após:','(A) 10 anos de serviço público em qualquer ente federativo.\n(B) 15 anos de serviço exclusivamente estadual.\n(C) 20 anos de serviço público municipal ou estadual.\n(D) 25 anos de efetivo exercício de serviço público estadual ou municipal, prestado exclusivamente no âmbito do Estado do Acre.\n(E) 30 anos de contribuição previdenciária.','D','O art. 36, § 4º, da Constituição Estadual, com redação da EC nº 36/2005, exige 25 anos de efetivo exercício de serviço público estadual ou municipal prestado exclusivamente no âmbito do Acre.'),
('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-law3228-chefia-11','Lei nº 3.228/2017 — gratificação de chefia','A gratificação de chefia prevista no art. 5º, VII, da Lei nº 3.228/2017 deve ser compreendida como:','(A) Parcela fixa paga automaticamente a todo Oficial Investigador.\n(B) Percentual universal de 20% sobre o vencimento básico.\n(C) Vantagem prevista no plano, cujo pagamento depende do exercício/designação e das regras específicas aplicáveis.\n(D) Parcela absorvida no vencimento básico.\n(E) Benefício pago apenas após 25 anos de serviço.','C','O art. 5º, VII, inclui a gratificação de chefia entre as vantagens, mas não estabelece pagamento automático nem percentual universal. O caso concreto depende de designação e norma específica aplicável.')
) as t(material_slug,external_item_key,subtopic,question_text,options_text,answer,explanation))
insert into public.curated_question_catalog
(source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,question_text,official_answer,explanation,difficulty,content_status,is_original,state,career_category,role_type,tested_topic,import_content_key,import_unique_key,didactic_provenance)
